        >
          <Plus size={24} />
        </button>
      </div>

      {isAdding && (
        <div className="glass-card p-6 rounded-3xl shadow-md border-pink-100 animate-slide-up">
          <h3 className="font-bold text-gray-800 mb-4">Tambah Sesi Baru</h3>
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-pink-600 uppercase mb-2">Durasi (Menit)</label>
              <div className="flex items-center gap-4">
                <input 
                  type="range" min="1" max="60" 
                  value={duration}
                  onChange={(e) => setDuration(e.target.value)}
                  className="w-full accent-pink-500"
                />
                <span className="font-bold text-pink-700 w-12">{duration}m</span>
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-pink-600 uppercase mb-2">Sisi Payudara</label>
              <div className="grid grid-cols-3 gap-2">
                {(['Left', 'Right', 'Both'] as const).map(s => (
                  <button
                    key={s}
