                      side === s ? 'bg-pink-500 text-white border-pink-500' : 'bg-white text-gray-600 border-gray-100'
                    }`}
                  >
                    {s === 'Left' ? 'Kiri' : s === 'Right' ? 'Kanan' : 'Keduanya'}
