            <button 
              onClick={() => { setIsRegistering(!isRegistering); setAuthError(''); }}
              className="text-pink-600 font-bold text-sm"
            >
              {isRegistering ? 'Sudah punya akun? Login' : 'Belum punya akun? Daftar'}
            </button>
          </div>
          {CONFIG.DEBUG_MODE && <p className="text-center text-[10px] text-gray-400">DEBUG MODE: Gunakan HP 123 Pass 123</p>}
        </div>
      </div>
    );
  }

  const renderDashboard = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black text-gray-800">Halo, {currentUser.name}! 🌸</h1>
          <p className="text-gray-500 text-sm">Semangat mengASIhi hari ini.</p>
        </div>
        <div className="w-12 h-12 bg-pink-100 rounded-full flex items-center justify-center text-pink-500">
          <Heart fill="currentColor" size={24} />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-gradient-to-br from-pink-400 to-rose-400 p-5 rounded-3xl text-white shadow-lg shadow-pink-100">
          <div className="flex justify-between items-start mb-4">
            <Activity size={24} />
            <span className="text-[10px] bg-white/20 px-2 py-0.5 rounded-full">HARI INI</span>
          </div>
          <p className="text-3xl font-bold">{summary.count}</p>
          <p className="text-xs opacity-80">Sesi Menyusui</p>
        </div>
        <div className="bg-gradient-to-br from-indigo-400 to-blue-400 p-5 rounded-3xl text-white shadow-lg shadow-blue-100">
          <div className="flex justify-between items-start mb-4">
            <Clock size={24} />
            <span className="text-[10px] bg-white/20 px-2 py-0.5 rounded-full">DURASI</span>
          </div>
          <p className="text-3xl font-bold">{summary.totalTime}</p>
          <p className="text-xs opacity-80">Total Menit</p>
        </div>
      </div>

      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="font-bold text-gray-800">Videos Rekomendasi</h3>
        </div>
        <div className="flex gap-4 overflow-x-auto pb-4 custom-scrollbar">
          {RECOMMENDED_VIDEOS.map((video) => (
            <div 
              key={video.id} 
              onClick={() => window.open(video.url, '_blank')}
              className="flex-shrink-0 w-64 glass-card rounded-3xl overflow-hidden border-white cursor-pointer group"
            >
              <div className="relative">
                <img src={video.thumbnail} alt={video.title} className="w-full h-32 object-cover" />
                <div className="absolute inset-0 bg-black/20 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                  <PlayCircle className="text-white" size={40} />
                </div>
              </div>
              <div className="p-4">
                <h4 className="font-bold text-gray-800 text-sm leading-tight line-clamp-2">{video.title}</h4>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-pink-50 p-6 rounded-3xl border border-pink-100 relative overflow-hidden group">
        <div className="relative z-10">
          <h3 className="text-pink-800 font-bold mb-1">Butuh Bantuan Ahli?</h3>
          <p className="text-pink-600 text-sm mb-4">Konsultasi langsung dengan konselor laktasi kami.</p>
          <button 
            onClick={() => window.open(CONFIG.CONSULTATION_EXTERNAL_URL, '_blank')}
            className="bg-pink-500 text-white px-5 py-2.5 rounded-xl font-bold text-sm shadow-md active:scale-95 transition-transform"
          >
            Konsultasi Sekarang
          </button>
        </div>
        <div className="absolute -right-4 -bottom-4 opacity-10 group-hover:scale-110 transition-transform">
          <Phone size={120} />
        </div>
      </div>
    </div>
  );

  const renderProfile = () => (
    <div className="space-y-6 animate-fade-in">
      <h2 className="text-2xl font-black text-gray-800">Profil Mama</h2>

      <div className="glass-card p-8 rounded-[40px] text-center border-white">
        <div className="w-24 h-24 bg-pink-100 text-pink-500 rounded-full flex items-center justify-center mx-auto mb-4 border-4 border-white shadow-lg">
          <UserIcon size={48} />
        </div>
        <h3 className="text-xl font-bold text-gray-800">{currentUser.name}</h3>
        <p className="text-gray-500 text-sm">{currentUser.phone}</p>
      </div>

      <div className="space-y-3">
        <button className="w-full flex items-center justify-between p-5 bg-white rounded-3xl border border-gray-100">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-50 text-blue-500 rounded-xl"><Heart size={20} /></div>
            <span className="font-bold text-gray-700">Pengaturan Akun</span>
          </div>
          <ChevronRight size={18} className="text-gray-300" />
        </button>
        <button className="w-full flex items-center justify-between p-5 bg-white rounded-3xl border border-gray-100">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-green-50 text-green-500 rounded-xl"><BookOpen size={20} /></div>
            <span className="font-bold text-gray-700">Tentang Aplikasi</span>
          </div>
          <ChevronRight size={18} className="text-gray-300" />
        </button>
        <button 
          onClick={handleLogout}
          className="w-full flex items-center gap-3 p-5 bg-red-50 text-red-600 rounded-3xl border border-red-100 font-bold"
        >
          <LogOut size={20} />
          Keluar
        </button>
      </div>
    </div>
  );

  return (
    <div className="max-w-md mx-auto min-h-screen pb-24 px-5 pt-6 relative overflow-x-hidden">
      {activeTab === AppTab.DASHBOARD && renderDashboard()}
      {activeTab === AppTab.EDUCATION && (
        !selectedArticle ? (
          <div className="space-y-4 animate-fade-in">
            <h2 className="text-2xl font-black text-gray-800 mb-6">Pusat Edukasi ASI</h2>
            <div className="grid gap-4">
              {EDUCATION_ARTICLES.map((article) => (
                <button 
                  key={article.id}
                  onClick={() => setSelectedArticle(article)}
                  className="w-full flex items-center gap-4 bg-white p-5 rounded-3xl border border-gray-100 text-left hover:shadow-sm"
                >
                  <div className="p-4 bg-pink-50 text-pink-500 rounded-2xl">
                    {getIcon(article.icon)}
                  </div>
                  <div>
                    <span className="text-[10px] font-bold text-pink-400 uppercase tracking-widest">{article.category}</span>
                    <h4 className="font-bold text-gray-800 text-lg">{article.title}</h4>
                  </div>
                </button>
              ))}
            </div>
          </div>
        ) : (
          <div className="animate-slide-right pb-24">
            <button onClick={() => setSelectedArticle(null)} className="text-pink-500 font-bold mb-6 flex items-center gap-1">← Kembali</button>
            <div className="glass-card p-8 rounded-[40px] shadow-sm">
              <h2 className="text-3xl font-black text-gray-800 mb-4">{selectedArticle.title}</h2>
              <p className="text-gray-600 leading-relaxed text-lg">{selectedArticle.content}</p>
            </div>
          </div>
        )
      )}
      {activeTab === AppTab.TRACKER && <TrackerSection />}
      {activeTab === AppTab.HEALTH && <BMISection />}
      {activeTab === AppTab.PROFILE && renderProfile()}

      <nav className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[90%] max-w-sm glass-card border-white/50 shadow-2xl rounded-[32px] px-2 py-3 flex items-center justify-around z-50">
        {[
          { tab: AppTab.DASHBOARD, icon: Home, label: 'Beranda' },
          { tab: AppTab.EDUCATION, icon: BookOpen, label: 'Materi' },
          { tab: AppTab.TRACKER, icon: Activity, label: 'Tracker' },
          { tab: AppTab.HEALTH, icon: Calculator, label: 'IMT' },
          { tab: AppTab.PROFILE, icon: UserIcon, label: 'Profil' }
        ].map(({ tab, icon: Icon, label }) => (
          <button 
            key={tab}
            onClick={() => { setActiveTab(tab); setSelectedArticle(null); }}
            className={`flex flex-col items-center gap-1 p-2 rounded-2xl transition-all ${activeTab === tab ? 'text-pink-500' : 'text-gray-400'}`}
          >
            <Icon size={22} strokeWidth={activeTab === tab ? 3 : 2} />
            <span className="text-[10px] font-bold">{label}</span>
          </button>
        ))}
      </nav>

      <style>{`
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes slideRight { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: translateX(0); } }
        @keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fadeIn 0.4s ease-out forwards; }
        .animate-slide-right { animation: slideRight 0.4s ease-out forwards; }
        .animate-slide-up { animation: slideUp 0.4s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

export default App;

